def suchen(k, x):
    if k is None:
        return False
    if x == k.wert:
        return True
    if x < k.wert:
        return suchen(k.links, x)
    return suchen(k.rechts, x)

print(suchen(wurzel, 40))  # True
print(suchen(wurzel, 60))  # False

class Knoten:
    def __init__(self, wert):
        self.wert = wert
        self.links = None
        self.rechts = None

def einfuegen(k, x):
    if k is None:
        return Knoten(x)
    if x < k.wert:
        k.links = einfuegen(k.links, x)
    elif x > k.wert:
        k.rechts = einfuegen(k.rechts, x)
    return k

wurzel = None
for x in [50, 30, 70, 20, 40, 80]:
    wurzel = einfuegen(wurzel, x)

print(wurzel.links.rechts.wert)  # 40
